  // ---------- graph helpers ----------
  function reaches(g, from, to) { const seen = {}; const stack = [from]; while (stack.length) { const x = stack.pop(); if (x === to) return true; if (seen[x]) continue; seen[x] = true; g.edges.forEach((e) => { if (e[0] === x) stack.push(e[1]); }); } return false; }
