    const ids = order(g); st.status = {}; st.run = null; st.running = true; st.tab = 'runs';
    const id = 'wr_' + Math.random().toString(36).slice(2, 10).toUpperCase();
    const rec = { id, trigger: (mode === 'dry-run' ? 'dry run, ' : 'manual, ') + 'Mara Okafor', started: 'just now', duration: '0 s', label: base.label, state: 'running', mode, version: mode === 'dry-run' ? 'draft' : (base.publishedVersion || base.version), as: 'Mara Okafor', done: [], skipped: [], detail: {} };
    st.extraRuns[st.wf] = [rec].concat(st.extraRuns[st.wf] || []);
    ctx.rerender(); ctx.toast(mode === 'dry-run' ? 'Dry run started: models, HTTP and record steps mocked, guardrails not consulted, nothing metered. The owner decides approvals.' : 'Run started (202). Steps report on the canvas as they run.');
    let i = 0; const t0 = Date.now(); const skip = {};
